WITH deduped AS (SELECT * FROM device_readings QUALIFY ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c DESC, id) = 1), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure, id) AS latest_rank FROM deduped QUALIFY latest_rank = 1), scored AS (SELECT *, MAX(status_bits) OVER w_recent AS device_code_max_status_bits, COUNT(pressure) OVER w_recent AS device_code_count_pressure, MAX(humidity) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS humidity_max_2h, SUM(pressure) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_pressure, CORR(temp_c, status_bits) OVER w_recent AS corr_temp_c_status_bits FROM latest WINDOW w_recent AS (PARTITION BY device_code)), metrics AS (SELECT id, reading_ts, temp_c, humidity, status_bits, firmware, latest_rank, device_code_max_status_bits, corr_temp_c_status_bits, SUM(humidity_max_2h) OVER w_part AS cumulative_humidity_max_2h, CORR(temp_c, humidity) OVER (PARTITION BY MONTH(reading_ts)) AS corr_temp_c_humidity, SUM(humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS humidity_sum_1h, FIRST_VALUE(humidity_max_2h, TRUE) OVER (ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_humidity_max_2h FROM scored WINDOW w_part AS (PARTITION BY DATE_TRUNC('WEEK', reading_ts), device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows AS (SELECT *, LAST_VALUE(temp_c, TRUE) OVER (ORDER BY corr_temp_c_status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_temp_c, SUM(device_code_max_status_bits) OVER (ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_device_code_max_status_bits, FIRST_VALUE(cumulative_humidity_max_2h) IGNORE NULLS OVER (ORDER BY humidity_sum_1h, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cumulative_humidity_max_2h FROM metrics WHERE corr_temp_c_humidity <= -0.4) SELECT id, temp_c, humidity, status_bits, firmware, latest_rank, device_code_max_status_bits, corr_temp_c_status_bits, cumulative_humidity_max_2h FROM with_windows ORDER BY corr_temp_c_status_bits;
